def _shape_vertices_um(shape: db.Shape, dbu: float) -> np.ndarray:
    """提取形状顶点（μm）。

    优先取 polygon 顶点；若为 box/path 则退化到包围盒四角。

    Args:
        shape: KLayout Shape。
        dbu: 数据库单位（μm）。

    Returns:
        (N, 2) 顶点数组（μm）。
    """
